// Writes src/config/noindex.js: /best/ topics with too few qualifying picks.
// Run after changing profiles or topics: pnpm --filter @linux-statistics/site best:noindex
import { writeFileSync } from "node:fs";
import { BEST_TOPICS, MIN_PICKS, bestPicks, isIndexable } from "../src/lib/best-for";
import { PROFILES } from "../src/lib/picker-profiles";

const thin = BEST_TOPICS.filter((t) => !isIndexable(bestPicks(t, PROFILES, () => null))).map((t) => `/best/${t.slug}/`).sort();
const body = `/**
 * Paths built with a robots noindex, kept out of the sitemap. Generated by
 * \`pnpm --filter @linux-statistics/site best:noindex\` from the /best/ topic
 * guard (topics with fewer than ${MIN_PICKS} qualifying picks); the test checks it is current.
 */
export const NOINDEX_PATHS = ${JSON.stringify(thin, null, 2)};
`;
writeFileSync(new URL("../src/config/noindex.js", import.meta.url), body);
console.log(`best:noindex: ${thin.length} thin topic(s): ${thin.join(", ") || "none"}`);
for (const t of BEST_TOPICS) console.log(`  ${t.slug}: ${bestPicks(t, PROFILES, () => null).map((p) => p.key).join(" ")}`);
